/**
 * Converts an infix expression to postfix (Reverse Polish Notation)
 * using the Shunting-yard algorithm.
 *
 * Supports: +, -, *, /, ^, parentheses, multi-digit numbers, and decimals.
 */
function infixToPostfix(expression) {
  const precedence = { '+': 1, '-': 1, '*': 2, '/': 2, '^': 3 };
  const rightAssociative = new Set(['^']);

  const output = [];
  const operatorStack = [];

  // Tokenize: numbers (including decimals) and operators/parens
  const tokens = expression.match(/\d+(\.\d+)?|[+\-*/^()]/g);
  if (!tokens) return '';

  for (const token of tokens) {
    if (/^\d/.test(token)) {
      output.push(token);
    } else if (token === '(') {
      operatorStack.push(token);
    } else if (token === ')') {
      while (operatorStack.length && operatorStack[operatorStack.length - 1] !== '(') {
        output.push(operatorStack.pop());
      }
      operatorStack.pop(); // discard '('
    } else {
      // operator
      while (
        operatorStack.length &&
        operatorStack[operatorStack.length - 1] !== '(' &&
        (precedence[operatorStack[operatorStack.length - 1]] > precedence[token] ||
          (precedence[operatorStack[operatorStack.length - 1]] === precedence[token] &&
            !rightAssociative.has(token)))
      ) {
        output.push(operatorStack.pop());
      }
      operatorStack.push(token);
    }
  }

  while (operatorStack.length) {
    output.push(operatorStack.pop());
  }

  return output.join(' ');
}

// ── Test Cases ──────────────────────────────────────────────────────────────

function assertEqual(actual, expected, label) {
  if (actual === expected) {
    console.log(`  PASS: ${label}`);
  } else {
    console.error(`  FAIL: ${label}\n    expected: "${expected}"\n    actual:   "${actual}"`);
  }
}

function runTests() {
  console.log('infixToPostfix tests:\n');

  // Basic operations
  assertEqual(infixToPostfix('3 + 4'), '3 4 +', 'simple addition');
  assertEqual(infixToPostfix('5 - 2'), '5 2 -', 'simple subtraction');
  assertEqual(infixToPostfix('6 * 3'), '6 3 *', 'simple multiplication');
  assertEqual(infixToPostfix('8 / 4'), '8 4 /', 'simple division');

  // Precedence
  assertEqual(infixToPostfix('3 + 4 * 2'), '3 4 2 * +', 'multiplication before addition');
  assertEqual(infixToPostfix('3 * 4 + 2'), '3 4 * 2 +', 'left multiplication');
  assertEqual(infixToPostfix('2 + 3 * 4 - 5'), '2 3 4 * + 5 -', 'mixed precedence');

  // Parentheses
  assertEqual(infixToPostfix('( 3 + 4 ) * 2'), '3 4 + 2 *', 'parens override precedence');
  assertEqual(infixToPostfix('( 1 + 2 ) * ( 3 + 4 )'), '1 2 + 3 4 + *', 'two paren groups');
  assertEqual(infixToPostfix('( ( 1 + 2 ) * 3 )'), '1 2 + 3 *', 'nested parens');

  // Right-associative exponent
  assertEqual(infixToPostfix('2 ^ 3'), '2 3 ^', 'simple exponent');
  assertEqual(infixToPostfix('2 ^ 3 ^ 2'), '2 3 2 ^ ^', 'right-associative exponent');
  assertEqual(infixToPostfix('2 * 3 ^ 2'), '2 3 2 ^ *', 'exponent before multiplication');

  // Multi-digit and decimal numbers
  assertEqual(infixToPostfix('10 + 20'), '10 20 +', 'multi-digit numbers');
  assertEqual(infixToPostfix('3.5 * 2.1'), '3.5 2.1 *', 'decimal numbers');

  // Complex expression
  assertEqual(
    infixToPostfix('( 1 + 2 ) * 3 ^ 2 - 4 / 2'),
    '1 2 + 3 2 ^ * 4 2 / -',
    'complex expression'
  );

  // Single token
  assertEqual(infixToPostfix('42'), '42', 'single number');

  console.log('\nAll tests complete.');
}

runTests();
